// Runtime configuration for Agile Poker frontend
// This file is generated by entrypoint.sh at container startup
// If not generated, fallback to defaults

(function() {
  if (!window.__RUNTIME_CONFIG__) {
    console.warn('[Config] Using default configuration - runtime config not found');
    window.__RUNTIME_CONFIG__ = {
      REACT_APP_API_URL: 'http://localhost:8000',
      REACT_APP_WS_URL: 'ws://localhost:8000',
      REACT_APP_JIRA_ENABLED: 'false',
      REACT_APP_LOG_LEVEL: 'info',
    };
  }
})();
